-- Ejecutar en Query Tool de pgAdmin conectado a NexaDB.
-- Creación inicial. Si las tablas ya existen, se cancela toda la operación.
-- Los nombres entre comillas coinciden con las propiedades del modelo EF Core.
BEGIN;

CREATE SCHEMA IF NOT EXISTS usuarios;

CREATE TABLE usuarios.personas (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Nombres" varchar(100) NOT NULL,
    "Apellidos" varchar(100) NOT NULL,
    "Documento" varchar(30),
    "Correo" varchar(254),
    "Telefono" varchar(30),
    "Direccion" varchar(300),
    "Activo" boolean NOT NULL DEFAULT true,
    "CreadoEn" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_personas" PRIMARY KEY ("Id"),
    CONSTRAINT ck_personas_nombres CHECK (length(btrim("Nombres")) > 0),
    CONSTRAINT ck_personas_apellidos CHECK (length(btrim("Apellidos")) > 0),
    CONSTRAINT ck_personas_documento CHECK (
        "Documento" IS NULL OR length(btrim("Documento")) > 0
    )
);

CREATE UNIQUE INDEX "IX_personas_Documento" ON usuarios.personas ("Documento");

CREATE TABLE usuarios.perfiles (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Nombre" varchar(50) NOT NULL,
    "Descripcion" varchar(250),
    "Activo" boolean NOT NULL DEFAULT true,
    "CreadoEn" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_perfiles" PRIMARY KEY ("Id"),
    CONSTRAINT ck_perfiles_nombre CHECK (
        length(btrim("Nombre")) > 0 AND "Nombre" = btrim("Nombre")
    )
);

CREATE UNIQUE INDEX "IX_perfiles_Nombre" ON usuarios.perfiles ("Nombre");

CREATE TABLE usuarios.usuarios (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "NombreUsuario" varchar(100) NOT NULL,
    "PasswordHash" varchar(512) NOT NULL,
    "Activo" boolean NOT NULL DEFAULT true,
    "CreadoEn" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "PersonaId" integer NOT NULL,
    "PerfilId" integer NOT NULL,
    CONSTRAINT "PK_usuarios" PRIMARY KEY ("Id"),
    CONSTRAINT ck_usuarios_nombre CHECK (
        length(btrim("NombreUsuario")) > 0
        AND "NombreUsuario" = lower(btrim("NombreUsuario"))
    ),
    CONSTRAINT ck_usuarios_password_hash CHECK (length(btrim("PasswordHash")) > 0),
    CONSTRAINT "FK_usuarios_personas_PersonaId" FOREIGN KEY ("PersonaId")
        REFERENCES usuarios.personas ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_usuarios_perfiles_PerfilId" FOREIGN KEY ("PerfilId")
        REFERENCES usuarios.perfiles ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_usuarios_NombreUsuario" ON usuarios.usuarios ("NombreUsuario");
CREATE UNIQUE INDEX "IX_usuarios_PersonaId" ON usuarios.usuarios ("PersonaId");
CREATE INDEX "IX_usuarios_PerfilId" ON usuarios.usuarios ("PerfilId");

COMMIT;

